@article{doi:10.1287/moor.2019.1003,
author = {Karimi, Mehdi and Tun\c{c}el, Levent},
title = {Primal–Dual Interior-Point Methods for Domain-Driven Formulations},
journal = {Mathematics of Operations Research},
volume = {45},
number = {2},
pages = {591-621},
year = {2020},
doi = {10.1287/moor.2019.1003},

URL = { 


        https://pubsonline.informs.org/doi/abs/10.1287/moor.2019.1003


},
eprint = { 


        https://pubsonline.informs.org/doi/pdf/10.1287/moor.2019.1003


}
,
    abstract = { We study infeasible-start, primal–dual interior-point methods for convex optimization problems given in a typically natural form we denote as domain-driven formulations. Our algorithms extend many advantages of primal–dual interior-point techniques available for conic formulations, such as the current best complexity bounds, and more robust certificates of approximate optimality, unboundedness, and infeasibility, to domain-driven formulations. The complexity results are new for the infeasible-start setup used even in the case of linear programming. In addition to complexity results, our algorithms aim for expanding the applications of and software for interior-point methods to wider classes of problems beyond optimization over symmetric cones. }
}

@article{doi:10.1287/moor.2017.0923,
author = {Bubeck, S\'{e}bastien and Eldan, Ronen},
title = {The Entropic Barrier: Exponential Families, Log-Concave Geometry, and Self-Concordance},
journal = {Mathematics of Operations Research},
volume = {44},
number = {1},
pages = {264-276},
year = {2019},
doi = {10.1287/moor.2017.0923},

URL = { 


        https://pubsonline.informs.org/doi/abs/10.1287/moor.2017.0923


},
eprint = { 


        https://pubsonline.informs.org/doi/pdf/10.1287/moor.2017.0923


}
,
    abstract = { We prove that the Cramér transform of the uniform measure on a convex body in ℝn is a (1 + o(1)) n-self-concordant barrier, improving a seminal result of Nesterov and Nemirovski. This gives the first explicit construction of a universal barrier for convex bodies with optimal self-concordance parameter. The proof is based on basic geometry of log-concave distributions and elementary duality in exponential families. As a side result, our calculations also show that the universal barrier of Nesterov and Nemirovski is exactly n-self-concordant on convex cones. }
}

